#!/usr/bin/env node
// Builds public/assets/rr-analytics.js — the analytics of src/lib/analytics.ts for pages without our React bundle
// (the Framer doctor pages load it from surgeon-pages.js). Runs before every build; tests/analytics.test.mjs fails if
// the committed file is stale.
//
//   node scripts/analytics-bundle.mjs
//
// IDs: VITE_GA_MEASUREMENT_ID and VITE_CLARITY_PROJECT_ID from the environment (Vercel), else from .env.production.
// The script does nothing on localhost unless the page URL has ?rr_analytics_debug=1 (then GA DebugView is on).

import { readFileSync, writeFileSync } from 'node:fs';
import ts from 'typescript';

const root = new URL('../', import.meta.url);
export const OUTPUT = new URL('public/assets/rr-analytics.js', root);

function envFile() {
  try {
    return Object.fromEntries(
      readFileSync(new URL('.env.production', root), 'utf8')
        .split('\n')
        .map((line) => /^\s*([A-Z_][A-Z0-9_]*)\s*=\s*(.*?)\s*$/.exec(line))
        .filter(Boolean)
        .map((m) => [m[1], m[2].replace(/^['"]|['"]$/g, '')]),
    );
  } catch {
    return {};
  }
}

export function config(env = { ...envFile(), ...process.env }) {
  return {
    ga: (env.VITE_GA_MEASUREMENT_ID || '').trim(),
    clarity: (env.VITE_CLARITY_PROJECT_ID || '').trim(),
  };
}

export function bundle({ ga, clarity } = config()) {
  const source = readFileSync(new URL('src/lib/analytics.ts', root), 'utf8');
  const code = ts.transpileModule(source, {
    compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2019, removeComments: true },
  }).outputText;
  return `// Generated by scripts/analytics-bundle.mjs from src/lib/analytics.ts. Do not edit; run the script instead.
(function () {
  var exports = {};
${code.replace(/^"use strict";\n/, '').trimEnd().replace(/^/gm, '  ')}
  var host = location.hostname;
  var debug = /[?&]rr_analytics_debug=1(&|$)/.test(location.search);
  var local = host === 'localhost' || host === '127.0.0.1' || host === '[::1]' || /\\.local$/.test(host);
  exports.initializeAnalytics({ measurementId: ${JSON.stringify(ga)}, clarityId: ${JSON.stringify(clarity)}, enabled: !local || debug, debug: debug });
})();
`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  writeFileSync(OUTPUT, bundle());
  const { ga, clarity } = config();
  console.log(`rr-analytics.js: GA ${ga || '(none)'}, Clarity ${clarity || '(none)'}`);
}
